=== FILE: deep_counter_formal.sv ===
// Formal property wrapper for deep_counter (task prj-784d6227b5:assertions-formal).
// Properties state interface_spec.md section 3 on the ports only.
// Immediate assertions inside always blocks, for the open Yosys front end.
// No assume statements: all inputs are free.
module deep_counter_formal #(
    parameter integer LIMIT = 99
) (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire       clr,
    output wire [6:0] count,
    output wire       carry
);
    deep_counter #(.LIMIT(LIMIT)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .en    (en),
        .clr   (clr),
        .count (count),
        .carry (carry)
    );

    // First-cycle guard for $past, and a record that reset has been applied.
    reg f_past_valid = 1'b0;
    reg f_reset_seen = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_seen <= 1'b1;
    end

    // Next-state behaviour, one assertion per rule.
    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:DC-RESET] rst_n low at an edge clears count.
            if (!$past(rst_n))
                assert(count == 7'd0);
            // [req:DC-CLEAR] clr clears count whatever en is.
            if ($past(rst_n) && $past(clr))
                assert(count == 7'd0);
            // [req:DC-COUNT] increment below LIMIT.
            if ($past(rst_n) && !$past(clr) && $past(en) && ($past(count) < LIMIT))
                assert(count == $past(count) + 7'd1);
            // [req:DC-COUNT] wrap to 0 at LIMIT.
            if ($past(rst_n) && !$past(clr) && $past(en) && ($past(count) == LIMIT))
                assert(count == 7'd0);
            // [req:DC-HOLD] no clear, no enable: count holds.
            if ($past(rst_n) && !$past(clr) && !$past(en))
                assert(count == $past(count));
        end
    end

    // [req:DC-RANGE] after reset, count never exceeds LIMIT.
    always @(*) begin
        if (f_reset_seen)
            assert(count <= LIMIT);
    end

    // [req:DC-CARRY] carry is high exactly when en, !clr and count == LIMIT.
    always @(*) begin
        assert(carry == (en && !clr && (count == LIMIT)));
    end

    // Covers: scenarios the proof must still allow.
    always @(posedge clk) begin
        // Full count reached after reset.
        cover(f_reset_seen && (count == LIMIT));
        // Carry raised after reset.
        cover(f_reset_seen && carry);
        // Top bit of count reached after reset.
        cover(f_reset_seen && count[6]);
        if (f_past_valid) begin
            // Wrap after reset: carry on one edge, count 0 on the next.
            cover($past(f_reset_seen) && $past(carry) && (count == 7'd0));
            // Clear and enable together from a non-zero count: clear wins.
            cover($past(rst_n) && $past(clr) && $past(en) && ($past(count) != 7'd0));
            // Hold at a non-zero count.
            cover($past(rst_n) && !$past(clr) && !$past(en) && ($past(count) != 7'd0));
        end
    end
endmodule
